/**
 * Bug-hunt repros for the OAuth-enabled Worker request path. Each test states
 * the behavior the Worker's own contract promises and fails on current code.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import type { HevyClient } from "@hevy-mcp/hevy-client";
import { createWorkerFetchHandler } from "./worker.js";
import { resetMemoryValidationCacheForTests } from "./validation-cache.js";
import { initializeMessage, jsonPostRequest } from "./test-fixtures/mcp.js";

const OAUTH_RESOURCE = "https://mcp.hevy-mcp.dev/mcp";
const REDIRECT_URI = "https://claude.ai/api/mcp/auth_callback";

function createTestExecutionContext(): ExecutionContext {
	const span = {
		isTraced: false,
		spanContext: () => ({ traceId: "", spanId: "", traceFlags: 0 }),
		setAttribute() {
			return span;
		},
		setAttributes() {
			return span;
		},
		recordException() {},
		updateName() {
			return span;
		},
		setStatus() {
			return span;
		},
		end() {},
	};
	return {
		waitUntil() {},
		passThroughOnException() {},
		abort() {},
		props: {},
		exports: {},
		tracing: {
			enterSpan: (_n: string, cb: (s: unknown) => unknown) => cb(span),
			startActiveSpan: (_n: string, cb: (s: unknown) => unknown) => cb(span),
			startSpan: () => span,
			getActiveSpan: () => undefined,
		},
	} as unknown as ExecutionContext;
}

function createMemoryKV() {
	const store = new Map<string, string>();
	return {
		store,
		get(key: string, options?: { type?: string } | string) {
			const value = store.get(key);
			if (value === undefined) return Promise.resolve(null);
			const type = typeof options === "string" ? options : options?.type;
			return Promise.resolve(type === "json" ? JSON.parse(value) : value);
		},
		put(key: string, value: string) {
			store.set(key, value);
			return Promise.resolve();
		},
		delete(key: string) {
			store.delete(key);
			return Promise.resolve();
		},
		list(options?: { prefix?: string }) {
			const prefix = options?.prefix ?? "";
			return Promise.resolve({
				keys: [...store.keys()]
					.filter((name) => name.startsWith(prefix))
					.map((name) => ({ name })),
				list_complete: true,
			});
		},
	};
}

function base64Url(bytes: Uint8Array): string {
	let binary = "";
	for (const byte of bytes) binary += String.fromCharCode(byte);
	return btoa(binary)
		.replaceAll("+", "-")
		.replaceAll("/", "_")
		.replace(/=+$/, "");
}

async function createPkcePair() {
	const verifier = base64Url(crypto.getRandomValues(new Uint8Array(32)));
	const challenge = base64Url(
		new Uint8Array(
			await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier)),
		),
	);
	return { verifier, challenge };
}

function createMockClient(): HevyClient {
	return {
		getUserInfo: vi.fn().mockResolvedValue({ data: { id: "user" } }),
	} as unknown as HevyClient;
}

function setup() {
	const handler = createWorkerFetchHandler({
		createValidationClient: () => createMockClient(),
		createRequestClient: () => createMockClient(),
	});
	const env = { OAUTH_KV: createMemoryKV() };
	return { handler, env };
}

type Setup = ReturnType<typeof setup>;

async function registerClient(
	{ handler, env }: Setup,
	clientName: string,
	redirectUri: string,
): Promise<string> {
	const registration = await handler(
		jsonPostRequest(
			{
				client_name: clientName,
				redirect_uris: [redirectUri],
				token_endpoint_auth_method: "none",
			},
			{ "content-type": "application/json" },
			"https://worker.example/register",
		),
		env,
		createTestExecutionContext(),
	);
	return ((await registration.json()) as { client_id: string }).client_id;
}

async function issueAccessToken(ctx: Setup, apiKey: string): Promise<string> {
	const { handler, env } = ctx;
	const clientId = await registerClient(ctx, "Test client", REDIRECT_URI);
	const { verifier, challenge } = await createPkcePair();
	const authorizeUrl = new URL("https://worker.example/authorize");
	authorizeUrl.searchParams.set("response_type", "code");
	authorizeUrl.searchParams.set("client_id", clientId);
	authorizeUrl.searchParams.set("redirect_uri", REDIRECT_URI);
	authorizeUrl.searchParams.set("state", "s");
	authorizeUrl.searchParams.set("code_challenge", challenge);
	authorizeUrl.searchParams.set("code_challenge_method", "S256");
	const consentHtml = await (
		await handler(new Request(authorizeUrl), env, createTestExecutionContext())
	).text();
	const encodedRequest = /name="oauth_request" value="([^"]+)"/.exec(
		consentHtml,
	)?.[1] as string;
	const approval = await handler(
		new Request("https://worker.example/authorize", {
			method: "POST",
			body: new URLSearchParams({
				oauth_request: encodedRequest,
				hevy_api_key: apiKey,
			}),
		}),
		env,
		createTestExecutionContext(),
	);
	const code = new URL(
		approval.headers.get("location") as string,
	).searchParams.get("code") as string;
	const tokens = (await (
		await handler(
			new Request("https://worker.example/token", {
				method: "POST",
				body: new URLSearchParams({
					grant_type: "authorization_code",
					code,
					redirect_uri: REDIRECT_URI,
					client_id: clientId,
					code_verifier: verifier,
				}),
			}),
			env,
			createTestExecutionContext(),
		)
	).json()) as { access_token: string };
	return tokens.access_token;
}

beforeEach(() => {
	vi.stubGlobal("Cloudflare", {
		compatibilityFlags: { global_fetch_strictly_public: true },
	});
	vi.spyOn(console, "log").mockImplementation(() => {});
	vi.spyOn(console, "warn").mockImplementation(() => {});
});

afterEach(() => {
	vi.unstubAllGlobals();
	vi.restoreAllMocks();
	resetMemoryValidationCacheForTests();
});

describe("bughunt: OAuth /mcp method contract matches the legacy path", () => {
	// Legacy /mcp answers GET/DELETE with 405 + Allow: POST, OPTIONS
	// (worker.test.ts "returns 405 for unsupported %s"), and the advertised
	// CORS_ALLOWED_METHODS is "POST, OPTIONS". OAuth-authenticated requests
	// skip that method gate and reach the stateless SDK transport directly.
	it("rejects GET /mcp with 405 instead of opening an unbounded SSE stream", async () => {
		const ctx = setup();
		const token = await issueAccessToken(ctx, "oauth-get-key");
		const result = await ctx.handler(
			new Request(OAUTH_RESOURCE, {
				method: "GET",
				headers: {
					accept: "text/event-stream",
					authorization: `Bearer ${token}`,
				},
			}),
			ctx.env,
			createTestExecutionContext(),
		);
		// Release the SDK keep-alive interval if the stream was opened.
		await result.body?.cancel();
		expect({
			status: result.status,
			contentType: result.headers.get("content-type"),
		}).toEqual({ status: 405, contentType: expect.not.stringContaining("event-stream") });
		expect(result.headers.get("allow")).toBe("POST, OPTIONS");
	});

	it("rejects DELETE /mcp with 405 like the legacy path", async () => {
		const ctx = setup();
		const token = await issueAccessToken(ctx, "oauth-delete-key");
		const result = await ctx.handler(
			new Request(OAUTH_RESOURCE, {
				method: "DELETE",
				headers: { authorization: `Bearer ${token}` },
			}),
			ctx.env,
			createTestExecutionContext(),
		);
		expect(result.status).toBe(405);
	});

	it("serves MCP only at exactly /mcp, not at /mcp/<anything>", async () => {
		const ctx = setup();
		const token = await issueAccessToken(ctx, "oauth-subpath-key");
		const result = await ctx.handler(
			jsonPostRequest(
				initializeMessage(1, "bughunt"),
				{
					accept: "application/json, text/event-stream",
					"content-type": "application/json",
					authorization: `Bearer ${token}`,
				},
				`${OAUTH_RESOURCE}/anything`,
			),
			ctx.env,
			createTestExecutionContext(),
		);
		await result.body?.cancel();
		// Legacy handler: any path other than /mcp is 404 "Not found".
		expect(result.status).toBe(404);
	});
});

describe("bughunt: consent page identifies where the code is sent", () => {
	// Dynamic client registration is open: anyone can register a client
	// named "Claude" with an attacker redirect_uri. The consent page shows
	// only the self-asserted client_name, so a victim cannot tell that their
	// Hevy API key (inside the grant) will be delivered to evil.example.
	// MCP Security Best Practices (consent UI): show the redirect_uri where
	// tokens will be sent.
	it("renders the redirect URI host on the consent page", async () => {
		const ctx = setup();
		const evilRedirect = "https://evil.example/callback";
		const clientId = await registerClient(ctx, "Claude", evilRedirect);
		const { challenge } = await createPkcePair();
		const url = new URL("https://worker.example/authorize");
		url.searchParams.set("response_type", "code");
		url.searchParams.set("client_id", clientId);
		url.searchParams.set("redirect_uri", evilRedirect);
		url.searchParams.set("state", "s");
		url.searchParams.set("code_challenge", challenge);
		url.searchParams.set("code_challenge_method", "S256");
		const page = await ctx.handler(
			new Request(url),
			ctx.env,
			createTestExecutionContext(),
		);
		const html = await page.text();
		expect(page.status).toBe(200);
		expect(html).toContain("<strong>Claude</strong> is requesting access");
		expect(html).toContain("evil.example");
	});
});
